calibration.python:
def words(s: str) -> list[str]:
    return [piece.casefold() for piece in s.split()]
assert words(' One  Two ') == ['one', 'two']

validation.python:
def pairs(xs):
    return list(zip(xs[::2], xs[1::2]))
assert pairs([3, 4, 5]) == [(3, 4)]

holdout.python:
def clamp_count(value, cap):
    return min(max(value, 0), cap)
assert clamp_count(-2, 7) == 0
